"""Every rounding rule of meterbill, in one place.

Nothing here reads or changes the decimal context: Decimal values are rounded
with exact integer arithmetic, so the results do not depend on the precision
or the rounding of the context, on the thread, or on the size of the numbers.
"""

from __future__ import annotations

import math
from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be a positive decimal")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _fraction(d: Decimal) -> Fraction:
    sign, digits, exp = d.as_tuple()
    n = int("".join(map(str, digits)) or "0")
    f = Fraction(n) * Fraction(10) ** exp
    return -f if sign else f


def _units(q: Fraction, method: str) -> int:
    """`q` rounded to a whole number by `method` (a non-negative `q`)."""
    whole, rest = divmod(q.numerator, q.denominator)
    if method == DOWN:
        return whole
    twice = 2 * rest
    if twice > q.denominator or (twice == q.denominator and (method == HALF_UP or whole % 2)):
        return whole + 1
    return whole


def _make(units: int, negative: bool, exp: int) -> Decimal:
    return Decimal((1 if negative else 0, tuple(int(c) for c in str(units)), exp))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; `method` decides ties and direction.

    The result carries the exponent of `step` and the sign of `value`, also
    when it is zero.
    """
    _check(value, step, method)
    _, digits, exp = step.as_tuple()
    unit = int("".join(map(str, digits)))
    q = abs(_fraction(value)) / (unit * Fraction(10) ** exp)
    return _make(_units(q, method) * unit, value.is_signed(), exp)


def _add(a: tuple, b: tuple) -> tuple:
    """(units, sign) pairs: the sum, with the sign of a zero as decimal addition gives it."""
    total = a[0] + b[0]
    return total, total < 0 or (total == 0 and a[1] and b[1])


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, each a multiple of `step`, adding up to the rounded sum.

    Each amount is cut down to a multiple of `step`; what the cuts lost against
    the sum rounded half up goes on the last amount that is not zero.
    """
    _, digits, exp = step.as_tuple()
    unit = int("".join(map(str, digits)))
    one = unit * Fraction(10) ** exp
    parts = [round_amount(a, step, DOWN) for a in amounts]
    pairs = []
    for p in parts:
        n = int("".join(map(str, p.as_tuple().digits))) // unit
        pairs.append((-n if p.is_signed() else n, p.is_signed()))
    exact = sum((_fraction(a) for a in amounts), Fraction(0))
    k = _units(abs(exact) / one, HALF_UP)
    whole = (-k if exact < 0 else k, exact < 0)
    cut = (0, False)
    for p in pairs:
        cut = _add(cut, p)
    rest = _add(whole, (-cut[0], not cut[1]))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            n, neg = _add(pairs[i], rest)
            parts[i] = _make(abs(n) * unit, neg, exp)
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    """A float settled to `places` the way the old customer system did it."""
    factor = 10**places
    return math.floor(value * factor + 0.5) / factor


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    """`value` with `places` digits after the point, rounded by `method`."""
    if isinstance(value, Decimal):
        if method not in _METHODS:
            raise ValueError(f"unknown rounding method: {method!r}")
        if not value.is_finite():
            return format(value, "f")
        return format(round_amount(value, _make(1, False, -places), method), "f")
    if not isinstance(value, float):
        raise TypeError("value must be a float or a Decimal")
    if method != HALF_EVEN:
        raise ValueError("a float is only rounded half to even")
    return format(value, f".{places}f")
