import random, math
from decimal import *
from meterbill import money
getcontext().rounding=ROUND_HALF_UP
R=random.Random(1)
def rd(): 
    return Decimal(R.choice(["-","",""])+str(R.randint(0,10**R.randint(1,12)))+"."+str(R.choice([0,5,50,500,R.randint(0,999999)])).zfill(R.randint(1,6)))
def orig_alloc(amounts):
    CENT=Decimal("0.01")
    parts=[a.quantize(CENT,rounding=ROUND_DOWN) for a in amounts]
    whole=sum(amounts,Decimal("0")).quantize(CENT,rounding=ROUND_HALF_UP)
    rest=whole-sum(parts,Decimal("0.00"))
    for i in range(len(parts)-1,-1,-1):
        if amounts[i]!=0:
            parts[i]+=rest;break
    return parts
for _ in range(30000):
    a=[rd()*R.choice([1,1,Decimal("0.001"),0]) for _ in range(R.randint(0,4))]
    o=[str(x) for x in orig_alloc(a)]; n=[str(x) for x in money.allocate(a,money.CENT)]
    assert o==n,(a,o,n)
    v=rd(); 
    for m,rm in((money.HALF_UP,ROUND_HALF_UP),(money.HALF_EVEN,ROUND_HALF_EVEN),(money.DOWN,ROUND_DOWN)):
        assert str(v.quantize(Decimal("0.01"),rounding=rm))==str(money.round_amount(v,money.CENT,m))
        assert format(v,".3f") if 0 else True
    for st in ["0.05","0.10","1","0.5","0.050","2"]:
        s=Decimal(st); t=rd()
        assert str((t/s).quantize(Decimal(1),rounding=ROUND_HALF_UP)*s)==str(money.round_amount(t,s,money.HALF_UP)),(t,s)
    t=rd(); o=Decimal(round(t)); n=money.round_amount(t,Decimal(1),money.HALF_EVEN); 
    assert o==n
    for p in range(0,5):
        for m,rm in((money.HALF_UP,ROUND_HALF_UP),(money.HALF_EVEN,ROUND_HALF_EVEN)):
